#include <stdio.h>

int main(void)
{
    int a = 7, b = 2;

    printf("%d\n", a / b);              /* 3    两个整数相除 -> 整数除法 */
    printf("%.1f\n", a / 2.0);          /* 3.5  一边是 double -> 浮点除法 */
    printf("%.1f\n", (double)a / b);    /* 3.5  先转换，再除 */
    printf("%.1f\n", (double)(a / b));  /* 3.0  先整数除，再转换（小数已经丢了） */
    printf("%d %d\n", -7 / 2, -7 % 2);  /* -3 -1 向零截断，余数符号跟被除数 */

    int x = 3.99;                        /* 3   赋值时直接截断，不是四舍五入 */
    printf("%d\n", x);

    double money = 100;
    printf("%.2f\n", money / 3);        /* 33.33 double / int 仍是浮点除法 */
    return 0;
}

