#include <stdio.h>

int main(void)
{
    int a = 8;
    int b = a--;        /* b 拿旧值 8，之后 a 变成 7 */
    int c = --a;        /* a 先减成 6，c 拿新值 6 */

    printf("第1次 a=%d b=%d c=%d\n", a, b, c);

    a -= 3;             /* a = 3 */
    b *= 3;             /* b = 24 */
    c /= 5;             /* c = 1，整数除法舍去 0.2 */

    printf("第2次 a=%d b=%d c=%d\n", a, b, c);

    a %= 5;             /* a = 3 */
    printf("第3次 a=%d\n", a);
    return 0;
}

#include <stdio.h>

int main(void)
{
    char c1 = '0';      /* 字符零：值是 ASCII 码 48 */
    int  i0 = 0;        /* 整数零：值就是 0 */
    char c2 = '\0';     /* 空字符：值是 0，用作字符串结束标志 */

    printf("'0'  值=%d sizeof=%zu\n", c1, sizeof(c1));
    printf("0    值=%d sizeof=%zu\n", i0, sizeof(i0));
    printf("'\\0' 值=%d sizeof=%zu\n", c2, sizeof(c2));
    printf("\"0\"  sizeof=%zu\n", sizeof("0"));
    printf("'7'-'0'=%d\n", '7' - '0');
    printf("c2==0 成立吗:%d  c1==0 成立吗:%d\n", c2 == 0, c1 == 0);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n;
    double price;
    char ch;

    if (scanf("%d", &n) != 1) {        /* 1) 必须传地址 &n  2) 检查返回值 */
        printf("整数读取失败\n");
        return 1;
    }
    if (scanf("%lf", &price) != 1) {   /* double 读入用 %lf（输出才用 %f） */
        printf("小数读取失败\n");
        return 1;
    }
    if (scanf(" %c", &ch) != 1) {      /* 前导空格：吃掉上一次输入留下的换行 */
        printf("字符读取失败\n");
        return 1;
    }

    printf("n=%d price=%.2f ch=%c\n", n, price, ch);
    printf("scanf 的返回值 = 成功读入的项数\n");
    return 0;
}

#include <stdio.h>

int main(void)
{
    char ch;

    if (scanf(" %c", &ch) != 1) {
        return 1;
    }

    printf("字符:%c ASCII:%d\n", ch, ch);

    if (ch >= 'A' && ch <= 'Z') {
        printf("大写字母 -> 小写:%c\n", ch + 32);
    } else if (ch >= 'a' && ch <= 'z') {
        printf("小写字母 -> 大写:%c\n", ch - 32);
    } else if (ch >= '0' && ch <= '9') {      /* 注意下界是 '0' 不是 '1' */
        printf("数字字符 -> 数值:%d\n", ch - '0');
    } else {
        printf("其它字符\n");
    }

    printf("常量对照 '0'=%d '9'=%d 'A'=%d 'a'=%d 差=%d\n", '0', '9', 'A', 'a', 'a' - 'A');
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 100 || n > 999) {
        printf("请输入三位正整数\n");
        return 1;
    }

    printf("原数:%d\n", n);
    printf("个位:%d 十位:%d 百位:%d\n", n % 10, n / 10 % 10, n / 100);
    printf("去掉个位:%d 去掉两位:%d\n", n / 10, n / 100);
    printf("各位之和:%d\n", n % 10 + n / 10 % 10 + n / 100);
    printf("逆序数:%d\n", n % 10 * 100 + n / 10 % 10 * 10 + n / 100);
    printf("边界 100 的逆序:%d\n", 100 % 10 * 100 + 100 / 10 % 10 * 10 + 100 / 100);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int w;
    double fee;

    if (scanf("%d", &w) != 1 || w < 0) {
        printf("请输入非负整数\n");
        return 1;
    }

    if (w > 20) {                                  /* 从高档往低档判断 */
        fee = 10 * 2 + 10 * 3 + (w - 20) * 5;
        printf("第三档:10吨x2 + 10吨x3 + %d吨x5\n", w - 20);
    } else if (w > 10) {
        fee = 10 * 2 + (w - 10) * 3;
        printf("第二档:10吨x2 + %d吨x3\n", w - 10);
    } else {
        fee = w * 2;
        printf("第一档:%d吨x2\n", w);
    }

    printf("水费:%.2f元\n", fee);
    printf("边界自查:10吨=%.2f 20吨=%.2f 21吨=%.2f\n", 10 * 2.0, 10 * 2 + 10 * 3.0,
           10 * 2 + 10 * 3 + 1 * 5.0);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n;
    int sum = 0;
    int count = 0;

    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("请输入正整数\n");
        return 1;
    }

    while (n > 0) {           /* 预习：条件为真就重复执行循环体 */
        sum += n % 10;        /* 取出最低位并累加 */
        n /= 10;              /* 去掉最低位 */
        count++;              /* 统计位数 */
    }

    switch (count) {          /* 预习：按位数分支，每个 case 都要 break */
        case 1: printf("一位数\n"); break;
        case 2: printf("两位数\n"); break;
        case 3: printf("三位数\n"); break;
        default: printf("四位及以上\n"); break;
    }

    printf("各位数字之和:%d\n", sum);
    printf("原数已被循环改成:%d（这就是为什么要先备份）\n", n);
    return 0;
}
